SELECT prep_crit_id AS prepCritId, goal_type AS goalType, item_type AS itemType, job_code_id AS jobCodeId, item_name AS itemName, info_url AS infoUrl, apply_url AS applyUrl, amount AS amount, amount_source AS amountSource, fee_detail AS feeDetail, external_code AS externalCode FROM prep_item_criteria WHERE goal_type = #{goalType} AND (job_code_id = #{jobCodeId} OR job_code_id IS NULL) AND del_yn = 'N' AND item_type IN
#{itemType}
ORDER BY item_type, prep_crit_id

